  "levels.features.chasm.no": "No, I changed my mind",
  "levels.features.chasm.ondeath": "You fell to death...",
  "levels.features.chasm.rankings_desc": "Died on Impact",
  "levels.features.chasm.yes": "Yes, I know what I'm doing",
