  "scenes.interlevelscene.file_not_found": "Save file not found. If this error persists after restarting, it may mean this save game is corrupted. Sorry about that.",
  "scenes.interlevelscene.io_error": "Cannot read save file. If this error persists after restarting, it may mean this save game is corrupted. Sorry about that.",
  "tiles.custom.carpet.desc": "Thick carpet covers the floor. It must be treated in some way, it isn't flammable.",
  "tiles.custom.carpet.name": "Carpet",
  "windows.wndblacksmith$hardenselector.prompt": "Harden an item",
  "windows.wndblacksmith$upgradeselector.prompt": "Upgrade an item",
  "windows.wndblacksmith$wndreforge.message": "Okay, I can reforge two identified items of the same type. The weaker one will be destroyed to give the stronger one an upgrade. If they're the same level, I'll keep the one on the left.",
  "windows.wndblacksmith$wndreforge.prompt": "Reforge an item",
  "windows.wndblacksmith$wndreforge.reforge": "Reforge them",
  "windows.wndblacksmith$wndsmith.prompt": "Okay, here's what I can make. I've already got the forge fired up so choose quickly.",
  "windows.wndblacksmith.cashout": "_Cash Out (all favor):_ I can just give you some regular gold I've got lyin' around. 1 for each point of favor.",
  "windows.wndblacksmith.cashout_no": "Nevermind.",
